item.content:encoded:
.header-transparent #Top_bar .top_bar_left
{
	background: #ffffff;
}

li a {
    color: #a14667;
}

li a:hover {
    color: #176973;
}

#Subheader 
{
     background-color: rgba(23,105,115,1); 
    background-image: linear-gradient(90deg,#a14667 0%,#1e3875 100%);
}


#Top_bar .menu > li.current-menu-item > a 
{
   background-color: red; 
	 border-radius: 8px;
	 color:#ffffff;
	 margin: 0px 5px 0px 5px;
	background-image: linear-gradient(90deg, #a14667 , #1e3875);
}

#Top_bar .menu > li > a:hover {
   background-color: red; 
	 border-radius: 8px;
	 color:#ffffff;
	background-image: linear-gradient(90deg, #a14667 , #1e3875);
}

.resp_bullets1
	{
	column-count: 3!important;;
	column-gap: 50px;
	list-style: initial;
	}

.resp_bullets2
	{
	column-count: 2!important;;
	column-gap: 50px;
	list-style: initial;
	}

.resp_bullets3
	{
	column-count: 2!important;;
	column-gap: 50px;
	list-style: initial;
	}

#Top_bar .menu > li > a
{
   padding: 0px 0;
}


@media only screen and (min-width: 767px)
{
#Top_bar .menu_wrapper
	{

    background-color: rgba(255,255,255,0.3);
    backdrop-filter: blur(5px);
		border-radius: 5px;
  }
}	



@media only screen and (min-width: 1240px)
{
  #Top_bar .menu_wrapper 
	{
    margin: 15px!important;
	}	
	#Top_bar.is-sticky .menu_wrapper
 {
   margin: 0px!important;
 }
 #Top_bar.is-sticky .top_bar_left
	{
		padding: 8px;
	}
	#Top_bar.is-sticky
	{
		height: 75px;
	}

}

@media only screen and (max-width: 767px)
{

 #Header{
		min-height: 60px!important;
	}	

	#Top_bar .responsive-menu-toggle
	{
	color:#000000;
	}

	#Side_slide #menu ul li a
	{ 
		border-radius: 8px;
	 color:#ffffff;
	 margin: 0px 5px 0px 5px;
	background-image: linear-gradient(90deg, #a14667 , #1e3875);
	}

	#Side_slide #menu ul li
	{
    width: 50%;
		padding:1px;
	}

	.resp_bullets1
	{
	column-count: 1!important;
	}

	.resp_bullets2
	{
	column-count: 1!important;
	}

 .resp_bullets3
	{
	column-count: 1!important;
	}


}

.post-nav.minimal a i
{
	color: #fff;
}

.arrow, .next, .prev {

	background-image: linear-gradient(90deg, #a14667 , #1e3875);
}

.fixed-nav .desc {
   color: #a14667;
}

.share-simple-wrapper {

    display: none;
}

#Side_slide {
    /*background-color: #ffffff!important;
    border-color: #191919;*/
	 background-color: rgba(255,255,255,0.3);
    backdrop-filter: blur(5px);
}

#Side_slide a:not(.button) {
    color: black;
}

.widget_type_1 .type_1_small , .widget_type_1 .bottom_branding
{
	display: none;
}

.widget_type_1 .type_1_big
{
	margin:0px!important;
}

wp:postmeta.wp:meta_value:
.header-transparent #Top_bar .top_bar_left {
    background: transparent!important;
}
.mfn-icon-box-top.mfn-icon-box-center .icon-wrapper  
{
    width: 150px!important;
    height: 150px!important;
}

.image_frame.mfn-mask-shape.circle img 
{
    background-color: #ffffff;
}

@media only screen and (max-width: 767px)
{
          #Top_bar
          {
              background-color: transparent!important;
              position: absolute!important;
          }
}

h4.title { 
text-overflow: ellipsis;
    overflow: hidden;
    white-space: nowrap;
 }

